  1 │ import { useEffect, useId, useReducer, useRef, type FormEvent, type InputHTMLAttributes, type ReactNode, type RefObject } from 'react';
  2 │ import { flushSync } from 'react-dom';
  3 │ import { cityName, formatDate, formatDayKey, formatTime, isValidTimeZone, localDate, zoneAbbreviation } from '../shared/time.ts';
  4 │ import { ApiError } from './api.ts';
  5 │ import {
  6 │   clockChange, DAYS_SHOWN, dayMixesOffsets, flowReducer, groupIntoDays, initialFlow, nearestOpenDays, nearestOpenTimes, sameZone,
  7 │   shownDayKey, zoneOptions, type Day, type Details,
  8 │ } from './booking.ts';
  9 │ import { useBookSlot, useSlots, useTimeZone } from './hooks.ts';
 10 │ import { Card, CardTitle, DemoBanner, primaryButton, Progress } from './ui.tsx';
 11 │ 
 12 │ // The day and slot radios are sr-only, so the global :focus-visible ring paints the hidden input. The visible box gets the same ring.
 13 │ const peerRing = 'peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-ink peer-focus-visible:ring-4 peer-focus-visible:ring-brand';
 14 │ const optionButton = 'rounded-field border border-field bg-white px-3 py-2 font-medium';
 15 │ const NOTHING_OPEN = `No times are open in the next ${DAYS_SHOWN} days. Please check back soon.`;
 16 │ 
 17 │ const DETAIL_FIELDS = ['parentName', 'parentEmail', 'childName'] as const;
 18 │ const fieldErrors = (error: unknown): Record<string, string> => (error instanceof ApiError && error.status === 400 ? error.fields : {});
 19 │ const hasDetailErrors = (error: unknown) => DETAIL_FIELDS.some((field) => fieldErrors(error)[field]);
 20 │ 
 21 │ export function BookingPage() {
 22 │   const [state, dispatch] = useReducer(flowReducer, initialFlow);
 23 │   const { timeZone, setTimeZone, deviceTimeZone } = useTimeZone();
 24 │   const { data, error, isFetching, refetch } = useSlots();
 25 │   const book = useBookSlot((startsAt) => {
 26 │     dispatch({ type: 'daySelected', dayKey: localDate(new Date(startsAt), timeZone) }); // stay on that day, even if it is now full
 27 │     dispatch({ type: 'slotUnavailable', startsAt });
 28 │   });
 29 │   // TanStack tells React about a pending mutation after a setTimeout(0), so a quick second click lands before the button disables
 30 │   const sending = useRef(false);
 31 │   const heading = useRef<HTMLHeadingElement>(null);
 32 │   const dayRow = useRef<HTMLDivElement>(null);
 33 │   const confirmButton = useRef<HTMLButtonElement>(null);
 34 │   const focusedStep = useRef(state.step);
 35 │   useEffect(() => {
 36 │     if (focusedStep.current === state.step) return; // the first load leaves focus alone
 37 │     focusedStep.current = state.step;
 38 │     heading.current?.focus();
 39 │   }, [state.step]);
 40 │ 
 41 │   const frame = (children: ReactNode) => (
 42 │     <>
 43 │       {data?.demo && <DemoBanner now={data.now} timeZone={timeZone} />}
 44 │       <Card>
 45 │         <Progress step={state.step === 'details' ? 1 : 2} />
 46 │         <CardTitle />
 47 │         {children}
 48 │       </Card>
 49 │     </>
 50 │   );
 51 │ 
 52 │   if (state.step === 'details') {
 53 │     return frame(
 54 │       <>
 55 │         <h2 ref={heading} tabIndex={-1} className="mt-6 text-lg font-bold">Your details</h2>
 56 │         <DetailsForm
 57 │           details={state.details}
 58 │           errors={fieldErrors(book.error)}
 59 │           onSubmit={(details) => {
 60 │             book.reset();
 61 │             dispatch({ type: 'detailsSubmitted', details });
 62 │           }}
 63 │         />
 64 │       </>,
 65 │     );
 66 │   }
 67 │ 
 68 │   // Back stays locked while a booking is in flight: resubmitting step 1 calls book.reset(), which drops this mutation's onError and would leave `sending` stuck
 69 │   const busy = book.isPending || book.isSuccess;
 70 │   const header = (
 71 │     <div className="mt-6 flex items-center gap-1">
 72 │       <button
 73 │         type="button"
 74 │         aria-label="Back to your details"
 75 │         disabled={busy}
 76 │         onClick={() => dispatch({ type: 'back' })}
 77 │         className="-ml-2 rounded-field p-1 enabled:hover:bg-brand-50 disabled:cursor-not-allowed disabled:text-ink-soft"
 78 │       >
 79 │         <Icon><path d="m12 19-7-7 7-7" /><path d="M19 12H5" /></Icon>
 80 │       </button>
 81 │       <h2 ref={heading} tabIndex={-1} className="text-lg font-bold">Pick a time</h2>
 82 │     </div>
 83 │   );
 84 │ 
 85 │   if (!data) {
 86 │     return frame(
 87 │       <>
 88 │         {header}
 89 │         {error && !isFetching ? (
 90 │           <div className="mt-6">
 91 │             <p role="alert">We couldn't load times.</p>
 92 │             <button type="button" onClick={() => void refetch()} className="mt-2 font-bold underline underline-offset-4">Try again</button>
 93 │           </div>
 94 │         ) : (
 95 │           <p role="status" className="mt-6">Loading times…</p>
 96 │         )}
 97 │       </>,
 98 │     );
 99 │   }
100 │ 
101 │   const now = new Date(data.now);
102 │   const days = groupIntoDays(data.slots, timeZone, now);
103 │   const shownSlots = days.flatMap((d) => d.slots);
104 │   const key = shownDayKey(days, state.selected, state.chosenDay, timeZone);
105 │   const day = days.find((d) => d.key === key)!;
106 │   // after a zone change the selected time can fall outside the 14 days shown; then nothing counts as selected
107 │   const selected = shownSlots.some((s) => s.startsAt === state.selected) ? state.selected : null;
108 │   const change = clockChange(days, timeZone, now);
109 │   const bookError = book.error;
110 │   const deviceCity = cityName(deviceTimeZone);
111 │   // the shown day can move to a chip scrolled out of sight, leaving nothing on screen that names it
112 │   const changeZone = (tz: string) => {
113 │     flushSync(() => setTimeZone(tz));
114 │     dayRow.current?.querySelector('input:checked')?.parentElement?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
115 │   };
116 │ 
117 │   const confirm = () => {
118 │     if (!selected || sending.current) return;
119 │     sending.current = true;
120 │     book.mutate(
121 │       { startsAt: selected, ...state.details, parentTimeZone: timeZone },
122 │       {
123 │         onError: (err) => {
124 │           sending.current = false;
125 │           if (hasDetailErrors(err)) dispatch({ type: 'back' });
126 │         },
127 │       },
128 │     );
129 │   };
130 │ 
131 │   return frame(
132 │     <>
133 │       {header}
134 │       <div className="mt-4">
135 │         <ZonePill timeZone={timeZone} now={now} onChange={changeZone} />
136 │         {isValidTimeZone(deviceTimeZone) && !sameZone(timeZone, deviceTimeZone) && (
137 │           <p className="mt-2 text-sm text-ink-soft">
138 │             Your device is set to {deviceCity} time.{' '}
139 │             <button type="button" onClick={() => changeZone(deviceTimeZone)} className="font-bold text-ink underline underline-offset-4">
140 │               Use {deviceCity} time
141 │             </button>
142 │           </p>
143 │         )}
144 │       </div>
145 │ 
146 │       <DayChips days={days} value={key} rowRef={dayRow} onChange={(dayKey) => dispatch({ type: 'daySelected', dayKey })} />
147 │ 
148 │       {change && key >= change.dayKey && (
149 │         <p className="mt-4 rounded-field bg-brand-50 p-3 text-sm">
150 │           Clocks in {cityName(timeZone)} change on {formatDayKey(change.dayKey)}. Times from then on are {change.to}, not {change.from}.
151 │           {dayMixesOffsets(day, timeZone) && ' On this day each time shows its zone.'}
152 │         </p>
153 │       )}
154 │ 
155 │       {day.openCount > 0 ? (
156 │         <SlotGrid
157 │           day={day}
158 │           timeZone={timeZone}
159 │           selected={state.selected}
160 │           onSelect={(startsAt) => dispatch({ type: 'slotSelected', startsAt })}
161 │         />
162 │       ) : (
163 │         <EmptyDay
164 │           days={days}
165 │           dayKey={key}
166 │           onJump={(dayKey) => {
167 │             dispatch({ type: 'daySelected', dayKey });
168 │             dayRow.current?.querySelector<HTMLInputElement>(`input[value="${dayKey}"]`)?.focus(); // the button that had focus goes away
169 │           }}
170 │         />
171 │       )}
172 │ 
173 │       {state.unavailable && (
174 │         <UnavailableAlert
175 │           startsAt={state.unavailable}
176 │           alternatives={nearestOpenTimes(shownSlots, state.unavailable)}
177 │           timeZone={timeZone}
178 │           shownKey={key}
179 │           onPick={(startsAt) => {
180 │             flushSync(() => dispatch({ type: 'slotSelected', startsAt })); // Confirm is disabled until this renders, and a disabled button takes no focus
181 │             confirmButton.current?.focus(); // the alert holding the clicked button goes away
182 │           }}
183 │         />
184 │       )}
185 │       {bookError && !(bookError instanceof ApiError && bookError.status === 409) && !hasDetailErrors(bookError) && (
186 │         <p role="alert" className="mt-4 text-sm text-alert">{bookError.message}</p>
187 │       )}
188 │ 
189 │       <button
190 │         ref={confirmButton}
191 │         type="button"
192 │         disabled={!selected || busy}
193 │         onClick={confirm}
194 │         className={`mt-6 ${primaryButton} disabled:cursor-not-allowed disabled:bg-full disabled:text-ink-soft`}
195 │       >
196 │         {busy ? 'Booking…' : selected ? `Confirm ${formatWhenShort(new Date(selected), timeZone)}` : 'Choose a time'}
197 │       </button>
198 │     </>,
199 │   );
200 │ }
201 │ 
202 │ /** 'Tue 27 Oct, 4:00 PM GMT' */
203 │ function formatWhenShort(at: Date, tz: string): string {
204 │   return `${formatDate(at, tz)}, ${formatTime(at, tz)} ${zoneAbbreviation(at, tz)}`;
205 │ }
206 │ 
207 │ function DetailsForm({ details, errors, onSubmit }: { details: Details; errors: Record<string, string>; onSubmit: (details: Details) => void }) {
208 │   const submit = (event: FormEvent<HTMLFormElement>) => {
209 │     event.preventDefault();
210 │     const form = new FormData(event.currentTarget);
211 │     const value = (name: keyof Details) => String(form.get(name)).trim();
212 │     onSubmit({ parentName: value('parentName'), parentEmail: value('parentEmail'), childName: value('childName') });
213 │   };
214 │   return (
215 │     <form onSubmit={submit} className="mt-4 flex flex-col gap-4">
216 │       <Field name="parentName" label="Parent's name" autoComplete="name" defaultValue={details.parentName} error={errors.parentName} />
217 │       <Field name="parentEmail" label="Parent's email" type="email" autoComplete="email" defaultValue={details.parentEmail} error={errors.parentEmail} />
218 │       <Field name="childName" label="Child's name" autoComplete="off" defaultValue={details.childName} error={errors.childName} />
219 │       <button type="submit" className={`mt-2 ${primaryButton}`}>Choose a time</button>
220 │     </form>
221 │   );
222 │ }
223 │ 
224 │ function Field({ name, label, error, ...input }: { name: keyof Details; label: string; error?: string } & InputHTMLAttributes<HTMLInputElement>) {
225 │   const id = useId();
226 │   return (
227 │     <div>
228 │       <label htmlFor={id} className="mb-1 block text-sm font-medium">{label}</label>
229 │       <input
230 │         {...input}
231 │         id={id}
232 │         name={name}
233 │         required
234 │         maxLength={80}
235 │         aria-invalid={error ? true : undefined}
236 │         aria-describedby={error ? `${id}-error` : undefined}
237 │         className="w-full rounded-field border border-field bg-white p-3 text-base aria-invalid:border-alert"
238 │       />
239 │       {error && <p id={`${id}-error`} className="mt-1 text-sm text-alert">{error}</p>}
240 │     </div>
241 │   );
242 │ }
243 │ 
244 │ function ZonePill({ timeZone, now, onChange }: { timeZone: string; now: Date; onChange: (tz: string) => void }) {
245 │   const options = zoneOptions(timeZone, now); // a shared, cached array: read it, never change it
246 │   const group = (name: 'common' | 'all') =>
247 │     options.filter((o) => o.group === name).map((o) => <option key={o.value} value={o.value}>{o.label}</option>);
248 │   return (
249 │     <div className="relative inline-flex items-center gap-2 rounded-cta border border-field bg-white px-4 py-2 text-sm font-medium has-focus-visible:outline-2 has-focus-visible:outline-offset-2 has-focus-visible:outline-ink has-focus-visible:ring-4 has-focus-visible:ring-brand">
250 │       <Icon><circle cx="12" cy="12" r="10" /><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20" /><path d="M2 12h20" /></Icon>
251 │       {cityName(timeZone)}
252 │       <Icon><path d="m6 9 6 6 6-6" /></Icon>
253 │       <select aria-label="Time zone" value={timeZone} onChange={(e) => onChange(e.target.value)} className="absolute inset-0 cursor-pointer opacity-0">
254 │         <optgroup label="Common">{group('common')}</optgroup>
255 │         <optgroup label="All time zones">{group('all')}</optgroup>
256 │       </select>
257 │     </div>
258 │   );
259 │ }
260 │ 
261 │ function DayChips({ days, value, rowRef, onChange }: { days: Day[]; value: string; rowRef: RefObject<HTMLDivElement | null>; onChange: (dayKey: string) => void }) {
262 │   const scroll = (direction: 1 | -1) => rowRef.current?.scrollBy({ left: direction * rowRef.current.clientWidth });
263 │   const arrow = 'shrink-0 rounded-field p-1 text-ink-soft hover:bg-brand-50 hover:text-ink';
264 │   return (
265 │     <fieldset className="mt-6 min-w-0">{/* a fieldset is min-content wide by default, which would stretch the card to fit all 14 chips */}
266 │       <legend className="sr-only">Day</legend>
267 │       <div className="flex items-center gap-1">
268 │         <button type="button" aria-label="Earlier days" onClick={() => scroll(-1)} className={arrow}>
269 │           <Icon><path d="m15 18-6-6 6-6" /></Icon>
270 │         </button>
271 │         {/* the padding leaves room for the focus ring, which the scroll box would clip */}
272 │         <div ref={rowRef} className="flex min-w-0 flex-1 scroll-smooth gap-2 overflow-x-auto p-1 motion-reduce:scroll-auto">
273 │           {days.map((d) => {
274 │             const [weekday, ...date] = formatDayKey(d.key).split(' ');
275 │             return (
276 │               <label key={d.key} className="relative shrink-0">
277 │                 <input type="radio" name="day" value={d.key} checked={d.key === value} onChange={() => onChange(d.key)} className="peer sr-only" />
278 │                 <span className={`flex w-18 cursor-pointer flex-col overflow-hidden rounded-field border border-field text-center peer-checked:border-brand peer-checked:bg-brand-100 ${d.openCount ? 'bg-white' : 'bg-full text-ink-soft'} ${peerRing}`}>
279 │                   <span className="pt-2 text-xs">{weekday}</span>{' '}
280 │                   <span className="pb-2 font-bold">{date.join(' ')}</span>{' '}
281 │                   <span className={`py-1 text-xs ${d.openCount ? 'bg-brand-50' : ''}`}>
282 │                     {d.openCount === 0 ? 'Full' : d.openCount === 1 ? '1 slot' : `${d.openCount} slots`}
283 │                   </span>
284 │                 </span>
285 │               </label>
286 │             );
287 │           })}
288 │         </div>
289 │         <button type="button" aria-label="Later days" onClick={() => scroll(1)} className={arrow}>
290 │           <Icon><path d="m9 18 6-6-6-6" /></Icon>
291 │         </button>
292 │       </div>
293 │     </fieldset>
294 │   );
295 │ }
296 │ 
297 │ function SlotGrid({ day, timeZone, selected, onSelect }: { day: Day; timeZone: string; selected: string | null; onSelect: (startsAt: string) => void }) {
298 │   const showZone = dayMixesOffsets(day, timeZone); // the change day repeats or skips an hour, so a bare "1:00 AM" would be ambiguous
299 │   return (
300 │     <fieldset className="mt-4">
301 │       <legend className="sr-only">Times on {formatDayKey(day.key)}</legend>
302 │       <div className="grid grid-cols-[repeat(auto-fill,minmax(7rem,1fr))] gap-2">
303 │         {day.slots.map((s) => {
304 │           const at = new Date(s.startsAt);
305 │           return (
306 │             <label key={s.startsAt} className="relative">
307 │               <input
308 │                 type="radio"
309 │                 name="slot"
310 │                 value={s.startsAt}
311 │                 checked={s.startsAt === selected}
312 │                 disabled={!s.available}
313 │                 onChange={() => onSelect(s.startsAt)}
314 │                 className="peer sr-only"
315 │               />
316 │               <span className={`flex cursor-pointer flex-col items-center rounded-field border border-field bg-white py-3 text-sm font-medium peer-checked:border-brand peer-checked:bg-brand peer-checked:font-bold peer-disabled:cursor-not-allowed peer-disabled:border-line peer-disabled:bg-full peer-disabled:text-ink-soft ${peerRing}`}>
317 │                 {formatTime(at, timeZone)}{showZone && ` ${zoneAbbreviation(at, timeZone)}`}
318 │                 {!s.available && <>{' '}<span className="text-xs">Full</span></>}
319 │               </span>
320 │             </label>
321 │           );
322 │         })}
323 │       </div>
324 │       {day.slots.some((s) => !s.available) && <p className="mt-3 text-sm text-ink-soft">Greyed-out times are full: every mentor is booked then.</p>}
325 │     </fieldset>
326 │   );
327 │ }
328 │ 
329 │ function EmptyDay({ days, dayKey, onJump }: { days: Day[]; dayKey: string; onJump: (dayKey: string) => void }) {
330 │   const { before, after } = nearestOpenDays(days, dayKey);
331 │   const nearest = [before, after].filter((d) => d !== null);
332 │   return (
333 │     <div className="mt-4 rounded-field bg-full p-4 text-sm">
334 │       <p className="font-bold">Every mentor is booked on {formatDayKey(dayKey)}.</p>
335 │       {nearest.length ? (
336 │         <>
337 │           <p className="mt-1">The nearest days with open times:</p>
338 │           <div className="mt-3 flex flex-wrap gap-2">
339 │             {nearest.map((d) => (
340 │               <button key={d.key} type="button" onClick={() => onJump(d.key)} className={optionButton}>
341 │                 {formatDayKey(d.key)} · {d.openCount} {d.openCount === 1 ? 'time' : 'times'}
342 │               </button>
343 │             ))}
344 │           </div>
345 │         </>
346 │       ) : (
347 │         <p className="mt-1">{NOTHING_OPEN}</p>
348 │       )}
349 │     </div>
350 │   );
351 │ }
352 │ 
353 │ function UnavailableAlert({ startsAt, alternatives, timeZone, shownKey, onPick }: {
354 │   startsAt: string; alternatives: string[]; timeZone: string; shownKey: string; onPick: (startsAt: string) => void;
355 │ }) {
356 │   const at = new Date(startsAt);
357 │   return (
358 │     <div role="alert" className="mt-4 rounded-field border border-alert bg-alert-50 p-4 text-sm">
359 │       <p className="font-bold text-alert">
360 │         Sorry, {formatTime(at, timeZone)} {zoneAbbreviation(at, timeZone)} on {formatDate(at, timeZone)} is no longer available.
361 │       </p>
362 │       {alternatives.length ? (
363 │         <>
364 │           <p className="mt-1">The nearest open times are below. Pick one and confirm again. Your details are kept.</p>
365 │           <div className="mt-3 flex flex-wrap gap-2">
366 │             {alternatives.map((t) => {
367 │               const alt = new Date(t);
368 │               return (
369 │                 <button key={t} type="button" onClick={() => onPick(t)} className={optionButton}>
370 │                   {localDate(alt, timeZone) === shownKey ? `${formatTime(alt, timeZone)} ${zoneAbbreviation(alt, timeZone)}` : formatWhenShort(alt, timeZone)}
371 │                 </button>
372 │               );
373 │             })}
374 │           </div>
375 │         </>
376 │       ) : (
377 │         <p className="mt-1">{NOTHING_OPEN}</p>
378 │       )}
379 │     </div>
380 │   );
381 │ }
382 │ 
383 │ function Icon({ children }: { children: ReactNode }) {
384 │   return (
385 │     <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="size-5 shrink-0">
386 │       {children}
387 │     </svg>
388 │   );
389 │ }

  1 │ // Pure booking logic for the browser: no React, no DOM, and no clock. Every day key comes from time.ts,
  2 │ // because a UTC-midnight Date read with a local getter lands on the wrong day in the US.
  3 │ import {
  4 │   addDays, canonicalTimeZone, formatZoneOption, isValidTimeZone, localDate, offsetMinutes, zoneAbbreviation,
  5 │   zonedTimeToInstant,
  6 │ } from '../shared/time.ts';
  7 │ import type { SlotDto } from '../shared/types.ts';
  8 │ 
  9 │ export const DAYS_SHOWN = 14;
 10 │ export const COMMON_ZONES = ['America/Los_Angeles', 'America/Denver', 'America/Phoenix', 'America/Chicago', 'America/New_York',
 11 │   'America/Anchorage', 'Pacific/Honolulu', 'Europe/London', 'Europe/Dublin', 'Asia/Kolkata'];
 12 │ 
 13 │ export type Day = { key: string; slots: SlotDto[]; openCount: number };
 14 │ 
 15 │ /** Exactly 14 local days from today in `tz`, each holding the slots that start on it. */
 16 │ export function groupIntoDays(slots: SlotDto[], tz: string, now: Date): Day[] {
 17 │   const today = localDate(now, tz);
 18 │   const days: Day[] = Array.from({ length: DAYS_SHOWN }, (_, i) => ({ key: addDays(today, i), slots: [], openCount: 0 }));
 19 │   const byKey = new Map(days.map((d) => [d.key, d]));
 20 │   for (const s of slots) {
 21 │     const day = byKey.get(localDate(new Date(s.startsAt), tz));
 22 │     if (!day) continue;
 23 │     day.slots.push(s);
 24 │     if (s.available) day.openCount++;
 25 │   }
 26 │   return days;
 27 │ }
 28 │ 
 29 │ /** The day to show: the selected time's own day (it must stay on screen after a zone change), else the chosen day, else the first open one. */
