 38 │ /** The open times closest to `target` (never `target` itself), in time order. */
 39 │ export function nearestOpenTimes(slots: SlotDto[], target: string, count = 3): string[] {
 40 │   const at = new Date(target).getTime();
 41 │   return slots
 42 │     .filter((s) => s.available && new Date(s.startsAt).getTime() !== at)
 43 │     .map((s) => ({ startsAt: s.startsAt, t: new Date(s.startsAt).getTime() }))
 44 │     .sort((a, b) => Math.abs(a.t - at) - Math.abs(b.t - at) || a.t - b.t)
