 56 │ /** The first day in the window whose midday offset differs from today's, with the zone names either side. */
 57 │ export function clockChange(days: Day[], tz: string, now: Date): { dayKey: string; from: string; to: string } | null {
 58 │   const offset = offsetMinutes(now, tz);
