 80 │ /** One option per real zone, common zones first. The option for `current` carries `current`'s own spelling, or the select shows nothing. */
 81 │ export function zoneOptions(current: string, now: Date): ZoneOption[] {
 82 │   const key = `${current}|${Math.floor(now.getTime() / 3_600_000)}`; // the hour keeps offset labels fresh across a clock change
 83 │   if (last?.key !== key) last = { key, options: buildZoneOptions(current, now) };
 84 │   return last.options;
