 87 │ function buildZoneOptions(current: string, now: Date): ZoneOption[] {
 88 │   const currentZone = canonicalTimeZone(current);
 89 │   const seen = new Set<string>();
 90 │   const options: ZoneOption[] = [];
 91 │   const add = (tz: string, group: 'common' | 'all') => {
 92 │     const zone = canonicalTimeZone(tz);
 93 │     if (seen.has(zone)) return; // 'Asia/Kolkata' and 'Asia/Calcutta' are one zone
 94 │     seen.add(zone);
 95 │     const value = zone === currentZone ? current : tz;
 96 │     options.push({ value, label: formatZoneOption(now, value), group });
 97 │   };
 98 │   for (const tz of COMMON_ZONES) add(tz, 'common');
 99 │   for (const tz of Intl.supportedValuesOf('timeZone')) add(tz, 'all');
100 │   // ICU's list lacks 'UTC' (a US browser behind UTC reports it), and can lack the exact zone a device reports
101 │   if (!seen.has(currentZone)) options.unshift({ value: current, label: formatZoneOption(now, current), group: 'common' });
102 │   return options;
