21 │ export async function migrate(pool: pg.Pool): Promise<string[]> {
22 │   const dir = new URL('../../migrations/', import.meta.url);
23 │   const client = await pool.connect();
24 │   try {
25 │     await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
26 │     await client.query(
27 │       'create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())',
28 │     );
29 │     const done = new Set((await client.query('select name from schema_migrations')).rows.map((r) => r.name));
30 │     const applied: string[] = [];
31 │     for (const name of (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()) {
32 │       if (done.has(name)) continue;
33 │       const sql = await readFile(new URL(name, dir), 'utf8');
34 │       try {
35 │         await client.query('begin');
36 │         await client.query(sql);
37 │         await client.query('insert into schema_migrations (name) values ($1)', [name]);
38 │         await client.query('commit');
39 │       } catch (err) {
40 │         await client.query('rollback');
41 │         throw err;
42 │       }
43 │       applied.push(name);
44 │     }
45 │     return applied;
46 │   } finally {
47 │     try {
48 │       await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]);
49 │     } finally {
50 │       client.release();
51 │     }
52 │   }
53 │ }
